def check_job_deadline(job_j_k):
    absolute_deadline = job_j_k.r + job_j_k.task.D
    return job_j_k.f <= absolute_deadline

def is_work_conserving(scheduler, current_time, ready_tasks, active_cores):
    if len(ready_tasks) > 0:
        # Check if any core is idle
        for core in active_cores:
            if core.is_idle():
                return False # A core is idle but a task is ready
    return True # No ready tasks, or all cores are busy

def calculate_I_pre_i_k(job_j_k, task_i, r_j_k, d_j_k, schedule):
    interference_time = 0
    for t in range(r_j_k, d_j_k):
        if job_j_k.is_ready_at(t) and not job_j_k.is_executing_at(t):
            if task_i.is_executing_at(t, schedule):
                interference_time += 1 # Assuming discrete time units
    return interference_time

def calculate_I_sc_k(job_j_k, r_j_k, d_j_k, concurrent_tasks, C_miss):
    total_cache_interference = 0
    # This is a conceptual sketch; actual calculation is complex (IP formulation)
    for instruction_access in job_j_k.execution_path_in_window(r_j_k, d_j_k):
        if instruction_access.is_potential_cache_hit_in_isolation():
            if any_concurrent_task_causes_eviction(instruction_access, concurrent_tasks):
                total_cache_interference += C_miss
    return total_cache_interference

def calculate_I_sc_i_k(job_j_k, task_i, r_j_k, d_j_k, C_miss):
    total_cache_interference_from_i = 0
    # This is a conceptual sketch; actual calculation is complex (S_tau_i_tau_k * C_miss)
    for instruction_access in job_j_k.execution_path_in_window(r_j_k, d_j_k):
        if instruction_access.is_potential_cache_hit_in_isolation():
            if task_i.causes_eviction(instruction_access):
                total_cache_interference_from_i += C_miss
    return total_cache_interference_from_i

def calculate_I_bar_k(task_k, all_jobs_of_k):
    max_total_interference = 0
    for job_j_k in all_jobs_of_k:
        current_I_pre_k = calculate_I_pre_k(job_j_k.r, job_j_k.d, task_k)
        current_I_sc_k = calculate_I_sc_k(job_j_k.r, job_j_k.d, task_k)
        total_interference_for_job = current_I_pre_k + current_I_sc_k
        if total_interference_for_job > max_total_interference:
            max_total_interference = total_interference_for_job
    return max_total_interference

def is_schedulable_theorem1(task_set, m):
    for task_k in task_set:
        # Assume calculate_I_bar_k is available and returns the exact worst-case
        worst_case_total_interference = calculate_I_bar_k(task_k)
        if worst_case_total_interference + task_k.C >= task_k.D:
            return False # Task k is not schedulable
    return True # All tasks are schedulable

def calculate_I_bar_pre_k(task_k, all_jobs_of_k):
    max_pre_interference = 0
    for job_j_k in all_jobs_of_k:
        current_I_pre_k = calculate_I_pre_k(job_j_k.r, job_j_k.d, task_k)
        if current_I_pre_k > max_pre_interference:
            max_pre_interference = current_I_pre_k
    return max_pre_interference

def calculate_I_bar_sc_k(task_k, all_jobs_of_k):
    max_sc_interference = 0
    for job_j_k in all_jobs_of_k:
        current_I_sc_k = calculate_I_sc_k(job_j_k.r, job_j_k.d, task_k)
        if current_I_sc_k > max_sc_interference:
            max_sc_interference = current_I_sc_k
    return max_sc_interference

def is_schedulable_theorem2(task_set, m):
    for task_k in task_set:
        # Assume calculate_I_bar_pre_k and calculate_I_bar_sc_k are available
        upper_bound_pre_interference = calculate_I_bar_pre_k(task_k)
        upper_bound_sc_interference = calculate_I_bar_sc_k(task_k)

        total_upper_bound_execution_time = task_k.C + upper_bound_pre_interference + upper_bound_sc_interference

        if total_upper_bound_execution_time >= task_k.D:
            return False # Task k might not be schedulable
    return True # All tasks are schedulable (sufficient condition)

def calculate_W_nc_i_Dk(task_i, task_k_D, task_k_priority, task_i_priority):
    if task_i_priority > task_k_priority: # tau_i in hp(k)
        num_body_jobs = task_k_D // task_i.T
        omega_nc = min(task_k_D % task_i.T, task_i.C)
        return num_body_jobs * task_i.C + omega_nc
    else: # tau_i in lep(k)
        return 0

def calculate_N_i_Dk(task_i, task_k_D):
    # This assumes integer division for '/'
    return max(0, task_k_D - task_i.C - task_i.T + task_i.D) // task_i.T

def calculate_W_ci_i_Dk(task_i, task_k_D, task_k_priority, task_i_priority):
    if task_i_priority > task_k_priority: # tau_i in hp(k)
        N_i_Dk = calculate_N_i_Dk(task_i, task_k_D)
        omega_ci = min(task_i.C, max(0, task_k_D - task_i.C - task_i.T + task_i.D) % task_i.T)
        return (1 + N_i_Dk) * task_i.C + omega_ci
    else: # tau_i in lep(k)
        return min(task_k_D, task_i.C)

def calculate_I_bar_pre_k_upper_bound(task_k, task_set, m, C_star_values):
    Omega_k_C_star = calculate_Omega_k(task_k, task_set, m, C_star_values)
    return Omega_k_C_star / m

def group_HB_by_cache_line(HB_k, idx_function, N_cache_lines):
    m_k_u_sets = [[] for _ in range(N_cache_lines)]
    for m_k_x in HB_k:
        u = idx_function(m_k_x)
        if 0 <= u < N_cache_lines:
            m_k_u_sets[u].append(m_k_x)
    return m_k_u_sets

def group_CB_by_cache_line(CB_i, idx_function, N_cache_lines):
    e_i_u_sets = [[] for _ in range(N_cache_lines)]
    for m_i_x in CB_i:
        u = idx_function(m_i_x)
        if 0 <= u < N_cache_lines:
            e_i_u_sets[u].append(m_i_x)
    return e_i_u_sets

def calculate_S_tau_i_tau_k(task_i, task_k, N_cache_lines, N_i_u_map, N_k_u_map):
    S_val = 0
    for u in range(N_cache_lines):
        S_val += min(N_i_u_map.get(u, 0), N_k_u_map.get(u, 0))
    return S_val

def calculate_I_sc_i_k_one_job(task_i, task_k, N_cache_lines, N_i_u_map, N_k_u_map, C_miss):
    S_val = calculate_S_tau_i_tau_k(task_i, task_k, N_cache_lines, N_i_u_map, N_k_u_map)
    return S_val * C_miss

def ip_objective_function(N_i_k_vars, I_sc_i_k_values):
    total_interference = 0
    for i in N_i_k_vars:
        total_interference += N_i_k_vars[i] * I_sc_i_k_values[i]
    return total_interference # Maximize this value

class Job:
    def __init__(self, task, arrival_time, start_time=None, finish_time=None):
        self.task = task
        self.r = arrival_time
        self.s = start_time
        self.f = finish_time

    def get_execution_window_length(self):
        if self.s is not None and self.f is not None:
            return self.f - self.s
        else:
            # For initial calculation, use C_k as an approximation
            return self.task.C

def calculate_max_N_i_k(C_k_ew_length, task_i):
    # Assuming integer division for '/'
    return 1 + max(0, C_k_ew_length - task_i.T + task_i.D) // task_i.T

